// ==================== 吃饭睡觉打豆豆 - Egret引擎版 ====================
//
// 视觉系统："星夜糖果屋"（Starry Candy Cottage）
// --------------------------------------------------------------
// 主题：深夜空魔法绘本 × 放置点击 RPG。所有界面色彩从 THEME 统一取值，
// 避免各模块各自写颜色常量导致风格碎裂。修改整站风格只需动 THEME。
// --------------------------------------------------------------

// 全局工具函数：绘制一对眼睛（必须在所有绘制代码之前定义）
function drawEyesPair(g, x1, y1, x2, y2, r, pr) {
  g.lineStyle(0);
  g.beginFill(0xffffff);
  g.drawCircle(x1, y1, r);
  g.drawCircle(x2, y2, r);
  g.endFill();
  g.beginFill(0x000000);
  g.drawCircle(x1, y1 + 0.5, pr);
  g.drawCircle(x2, y2 + 0.5, pr);
  g.endFill();
  g.beginFill(0xffffff);
  g.drawCircle(x1 - pr * 0.5, y1 - pr * 0.5, pr * 0.5);
  g.drawCircle(x2 - pr * 0.5, y2 - pr * 0.5, pr * 0.5);
  g.endFill();
}

var THEME = {
  // 背景层（从深到浅）
  bgDeep:   0x0a0820,
  bgMid:    0x1a1340,
  bgLite:   0x2a1f5c,
  bgRow:    0x1a153f,
  bgGlass:  0x140e36,
  // 边框
  strokeGold: 0xf5c842,
  strokeSoft: 0x4a3a8c,
  // 主色
  accent:     0xfbbf24,
  accentSoft: 0xfde68a,
  pink:       0xff7eb0,
  mint:       0x7be8b7,
  sky:        0x5ec8ff,
  lavender:   0xc7a7ff,
  // 状态色
  ok:      0x2ecc71,
  warn:    0xf39c12,
  danger:  0xef4444,
  // 文字
  textMain: 0xffffff,
  textDim:  0xb8b0db,
  // 说明性文字的最低可用色：实测对比度 bgDeep 5.62 / bgMid 4.96 / panel 5.46，达 AA(4.5)。
  // textMute 只有 3.10~3.52，降级为装饰专用（占位符、未解锁图标），不再承载信息。
  textFaint: 0x8b83b4,
  textMute: 0x6a628f,
  textGold: 0xfbbf24
};

// 界面版式 token —— 与 docs/UI-SPEC.md v1.0 一一对应。
// 字号 7 档 / 圆角 5 档 / 间距 6 档，全项目只允许取这些值；新增字号或圆角先改规范再改这里。
var UI = {
  W: 375,          // 设计宽（fixedWidth，逻辑单位 = 375 宽的 1/375）
  M: 12,           // 页面外边距：HUD / 战斗区 / 面板内容统一走这一条竖线
  S1: 4, S2: 8, S3: 12, S4: 16, S5: 24, S6: 32,
  R_S: 4, R_M: 8, R_L: 12, R_XL: 16,
  // 字号：D 展示 / T1 标题 / T2 小标题 / T3 强调 / T4 正文 / T5 辅助 / T6 微
  D: 28, T1: 20, T2: 16, T3: 14, T4: 12, T5: 11, T6: 10,
  // 行高：标题类 ×1.3、正文类 ×1.4，取偶数；Label 的 height 必须 ≥ 行高，否则中文下伸部被裁。
  LH: { 28: 34, 20: 26, 16: 22, 14: 20, 12: 17, 11: 15, 10: 13 },
  HIT: 44,         // 最小点击热区
  HIT_MAIN: 96,
  // 战斗数字独立阶梯：常规 / 真伤 / 弱点 / 暴击
  DMG: { normal: 20, true: 22, weak: 24, crit: 28 }
};
function uiLH(size) { return UI.LH[size] || (size + 4); }

// R6 · 按钮视觉唯一来源。35 个 createButton 调用点原本散落 17 种底色、9 种高度，
// 同一种「确认 / 领取」在不同面板长得不一样。这里收敛成 6 档语义色 + 3 档高度
// （44 留给主行动），旧色值走 BTN_LEGACY 映射归位：调用点无需逐个改写，
// 以后新增按钮也不会再开出新档。改风格只动这一处。
var BTN = {
  primary:  0xd99022,  // 奖励 / 大额操作
  confirm:  0x27ae60,  // 确认 / 领取 / 升级
  action:   0x3498db,  // 次要动作 / 查看 / 页签选中
  special:  0x8e44ad,  // 转生 / 钻石 / 广告
  neutral:  0x30245f,  // 取消 / 页签未选中
  disabled: 0x555555,  // 禁用
  danger:   0xb01c33   // 危险
};
var BTN_LEGACY = {
  0x27ae60: BTN.confirm, 0x2d8f62: BTN.confirm, 0x2f6f5e: BTN.confirm, 0x2ecc71: BTN.confirm,
  0x3498db: BTN.action, 0x2980b9: BTN.action,
  0x8e44ad: BTN.special, 0x9b59b6: BTN.special, 0x4a2d6b: BTN.special,
  0x30245f: BTN.neutral, 0x3b3b46: BTN.neutral, 0x7f8c8d: BTN.neutral,
  0x555555: BTN.disabled,
  0xd99022: BTN.primary, 0xe67e22: BTN.primary, 0xf39c12: BTN.primary, 0xfbbf24: BTN.primary,
  0xe74c3c: BTN.danger, 0xb01c33: BTN.danger
};
function btnColor(c) { return BTN_LEGACY[c] !== undefined ? BTN_LEGACY[c] : c; }
function btnHeight(h) {
  if (h >= 44) return 44;
  if (h >= 34) return 34;
  if (h >= 28) return 30;
  return 26;
}

var ASSET_VERSION = (typeof BUILD_VERSION !== 'undefined' ? BUILD_VERSION : 'dev');
function assetUrl(path) {
  return path + '?v=' + ASSET_VERSION;
}

