// 法师是「表样板」，换回法师时要能原样还原，所以在载入时留一份深拷贝。
// 不用再手写第二份 —— 两份数据必然会漂。
var MAGE_SKILL_SNAPSHOT = JSON.parse(JSON.stringify(SKILLS));

// 唯一的技能表构建点：转职、读档、新开局都走这里。
// 原地改 SKILLS 的字段（不换数组、不换对象），所以所有 `SKILLS[i]` 的旧引用自动跟着变 ——
// 这也是这轮能改动 40 多处调用点却只改一个函数的原因。
function buildSkillTable(jobId) {
  var src = (jobId === 'trainee_mage' || !JOB_SKILL_KITS[jobId]) ? MAGE_SKILL_SNAPSHOT : JOB_SKILL_KITS[jobId];
  for (var i = 0; i < SKILL_SLOTS.length; i++) {
    var slot = SKILL_SLOTS[i];
    var from = src[i] || {};
    var dst = SKILLS[i] || (SKILLS[i] = {});
    dst.name = from.name || ('技能' + (i + 1));
    dst.role = from.role || slot.role;
    dst.lv = slot.lv;
    dst.cd = Number(from.cd) || 10;
    dst.dmg = Number(from.dmg) || 0;
    dst.hits = (from.hits === undefined) ? 1 : from.hits;
    dst.type = from.type || 'magic';
    dst.effect = from.effect || 'single';
    dst.kind = from.kind || '';
    // R81：颜色 / 辉光改成「按职业」。改前一律取 slot.color，六套职业同一位置
    // 是同一个颜色 —— 玩家换职业后看到的还是那七个颜色，视觉上等于没换。
    dst.color = (from.color === undefined) ? slot.color : from.color;
    dst.glow = (from.glow === undefined) ? slot.glow : from.glow;
    dst.icon = slot.icon;
    dst.grow = slot.grow;
    dst.vsBoss = Number(from.vsBoss) || 0;
    dst.energy = Number(from.energy) || 0;
    dst.healOnCast = Number(from.healOnCast) || 0;
    dst.armorGain = Number(from.armorGain) || 0;
    dst.healPerArmor = Number(from.healPerArmor) || 0;
    dst.armorScale = Number(from.armorScale) || 0;
    // 下面四个必须显式覆盖成 null：不覆盖的话，法师的护盾参数会被剑士的护盾位继承，
    // 表现就是「换了职业，减伤数值还是上一个职业的」。
    dst.buff = from.buff || null;
    dst.shield = from.shield || null;
    dst.heal = from.heal || null;
  }
  return SKILLS;
}
buildSkillTable('trainee_mage');

// 面板/文档要「只看某一职业的技能名」，不能为此真的切一次全局表。
function describeSkillKit(jobId) {
  var src = (jobId === 'trainee_mage' || !JOB_SKILL_KITS[jobId]) ? MAGE_SKILL_SNAPSHOT : JOB_SKILL_KITS[jobId];
  var out = [];
  for (var i = 0; i < SKILL_SLOTS.length; i++) out.push((src[i] && src[i].name) || '');
  return out;
}

// 怪物类型定义（三层光影风格）
//   highlight 浅色高光 / accent 点缀色（牙爪等）
// R62：怪物生态重做。改前这张表**只有数值没有身份**：
//   · 8 只怪的攻击全部走同一个 2.5 秒齐射节拍，谁打你、打多疼、多久打一次完全一样；
//   · soft / magicWall / ethereal 三个 trait 只写在数据里，代码里没有任何分支 —— 名字是空头支票；
//   · 抗性只有 armor / resist 两个数字，玩家能感知的只有「血条掉得慢」，感觉不到「这只怪克我」。
// 现在每只怪补四样能打出来的东西：
//   atkEvery  自己的出手间隔（不再是全场同一个节拍）
//   atkMul    单次伤害系数。快的轻、慢的重 —— 总伤害预算基本不变，节奏完全不同
//   jobResist 对某个**职业属性**的部分减免（0.16~0.30）。不是免疫：仍能打，只是用错人更慢
//   thorns    挨物理打时反弹给主角的伤害比例（只有刺球有，与骑士的反伤对称）
// 五条设计约束（写死在 probe:monsters 里，改数据会被门禁拦下）：
//   ① 没有任何一只怪同时抗两种属性 —— 每只都留一条打得通的路；
//   ② 每种伤害类型都至少被一只怪抗、也至少被一只怪弱 —— 没有通吃的职业；
//   ③ 抗性上限 0.30（BOSS 才是 0.30~0.45）——「比较难打」不是「打不动」；
//   ④ 出手间隔覆盖 1.5~4.2 秒，快慢差 ≥ 2.5 倍 —— 手感必须听得出来；
