  this.goldLabel.width = 100; this.goldLabel.height = 18; this.goldLabel.textAlign = 'right';
  this.goldLabel.x = resX + 26; this.goldLabel.y = 42;
  this.goldLabel.touchEnabled = false;
  topBar.addChild(this.goldLabel);
  goldPill.addEventListener(egret.TouchEvent.TOUCH_TAP, function() { self.openGoldInfo(); }, this);
  this.bindPressFeedback(goldPill);

  var gemPill = new eui.Rect();
  gemPill.width = 74; gemPill.height = 24; gemPill.ellipseWidth = 12; gemPill.ellipseHeight = 12;
  gemPill.fillColor = 0x19103d; gemPill.fillAlpha = 0.96;
  gemPill.strokeColor = THEME.lavender; gemPill.strokeWeight = 0.9; gemPill.strokeAlpha = 0.62;
  gemPill.x = 212; gemPill.y = 39;
  gemPill.touchEnabled = true;
  this.addHitPadding(gemPill, gemPill.width, gemPill.height);
  topBar.addChild(gemPill);
  var gemIcon = new eui.Image();
  this.fitImageToBox(gemIcon, UI_ASSETS.topHudDiamond, 20, 20, 216, 41);
