  topBar.addChild(gemIcon);
  this.gemsLabel = new eui.Label();
  this.gemsLabel.text = String(this.rebirthGems || 0);
  this.gemsLabel.size = 12; this.gemsLabel.textColor = 0xc7a7ff; this.gemsLabel.bold = true;
  this.gemsLabel.width = 42; this.gemsLabel.height = 18; this.gemsLabel.textAlign = 'right';
  this.gemsLabel.x = 238; this.gemsLabel.y = 42;
  this.gemsLabel.touchEnabled = false;
