  var stonePill = new eui.Group();
  stonePill.width = 72; stonePill.height = 44;
  stonePill.x = 290; stonePill.y = 29;
  stonePill.touchEnabled = true;
  var stoneBg = new eui.Rect();
  stoneBg.width = stonePill.width; stoneBg.height = 24; stoneBg.y = 10;
  stoneBg.ellipseWidth = 12; stoneBg.ellipseHeight = 12;
  stoneBg.fillColor = 0x2a1a0c; stoneBg.fillAlpha = 0.96;
  stoneBg.strokeColor = 0xe67e22; stoneBg.strokeWeight = 0.9; stoneBg.strokeAlpha = 0.64;
  stoneBg.touchEnabled = false;
  stonePill.addChild(stoneBg);
  var stoneIcon = new eui.Image();
  this.fitImageToBox(stoneIcon, UI_ASSETS.topHudStone, 20, 20, 4, 12);
