  this.stoneLabel.size = 12; this.stoneLabel.bold = true; this.stoneLabel.textColor = 0xffb15c;
  this.stoneLabel.width = stonePill.width - 32; this.stoneLabel.height = 18;
  this.stoneLabel.x = 26; this.stoneLabel.y = 13;
  this.stoneLabel.textAlign = 'right'; this.stoneLabel.verticalAlign = 'middle';
  this.stoneLabel.touchEnabled = false;
  stonePill.addChild(this.stoneLabel);
  stonePill.addEventListener(egret.TouchEvent.TOUCH_TAP, function() { self.openForgeStoneInfo(); }, this);
